    if source == target:
        return 0

    # Build adjacency list.
    adj = {}
    for u, v in edges:
        adj.setdefault(u, []).append(v)

    # BFS.
    from collections import deque
    visited = set([source])
    queue = deque([(source, 0)])

    while queue:
        node, dist = queue.popleft()
        for neigh in adj.get(node, []):
            if neigh == target:
                return dist + 1
            if neigh not in visited:
                visited.add(neigh)
                queue.append((neigh, dist + 1))

    # Target unreachable.
    return None

